    result["valuation_refs"] = [{key: workbook[key] for key in
                                  ("snapshot_id", "generation_id", "valuation_date")} | {
        "interpretation": "Synthetic replay reviewed these exact documented assumptions at the stated historical cutoff; this is not a live investment valuation."}]
    return result
